    it('should keep emphasis in a rejected reference link', () => {
      assert.strictEqual(
        marked.parse('[foo *bar [baz](/url) qux*][ref]\n\n[ref]: /uri').trim(),
        '<p>[foo <em>bar <a href="/url">baz</a> qux</em>]<a href="/uri">ref</a></p>',
      );
      assert.strictEqual(
        marked.parse('[foo _bar [baz](/url) qux_][ref]\n\n[ref]: /uri').trim(),
        '<p>[foo <em>bar <a href="/url">baz</a> qux</em>]<a href="/uri">ref</a></p>',
      );
      assert.strictEqual(
        marked.parse('[foo **bar [baz](/url) qux**][ref]\n\n[ref]: /uri').trim(),
        '<p>[foo <strong>bar <a href="/url">baz</a> qux</strong>]<a href="/uri">ref</a></p>',
      );
      assert.strictEqual(
        marked.parse('[foo *bar [baz][ref2] qux*][ref]\n\n[ref]: /uri\n[ref2]: /u2').trim(),
        '<p>[foo <em>bar <a href="/u2">baz</a> qux</em>]<a href="/uri">ref</a></p>',
